/* Halcyon Threshold — Site Styles */

:root {
    --color-bg: #fafafa;
    --color-text: #2d2d2d;
    --color-accent: #1a5f7a;
    --color-accent-light: #e8f4f8;
    --color-border: #e0e0e0;
    --font-main: 'Georgia', 'Times New Roman', serif;
    --font-heading: 'Helvetica Neue', 'Arial', sans-serif;
    --max-width: 720px;
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: var(--font-main);
    font-size: 18px;
    line-height: 1.7;
    color: var(--color-text);
    background: var(--color-bg);
    padding: 2rem 1.5rem;
}

header {
    max-width: var(--max-width);
    margin: 0 auto 3rem auto;
    padding-bottom: 2rem;
    border-bottom: 1px solid var(--color-border);
    text-align: center;
}

h1 {
    font-family: var(--font-heading);
    font-size: 2.5rem;
    font-weight: 300;
    letter-spacing: 0.05em;
    color: var(--color-accent);
    margin-bottom: 0.5rem;
}

.tagline {
    font-style: italic;
    color: #666;
    font-size: 1.1rem;
}

main {
    max-width: var(--max-width);
    margin: 0 auto;
}

section {
    margin-bottom: 3rem;
}

h2 {
    font-family: var(--font-heading);
    font-size: 1.4rem;
    font-weight: 600;
    color: var(--color-accent);
    margin-bottom: 1rem;
    letter-spacing: 0.02em;
}

p {
    margin-bottom: 1rem;
}

ul {
    margin: 1rem 0 1rem 1.5rem;
}

li {
    margin-bottom: 0.75rem;
}

strong {
    font-weight: 600;
}

.focus-grid {
    display: grid;
    gap: 1.5rem;
}

@media (min-width: 600px) {
    .focus-grid {
        grid-template-columns: repeat(3, 1fr);
    }
}

.focus-item {
    background: var(--color-accent-light);
    padding: 1.5rem;
    border-radius: 6px;
}

.focus-item h3 {
    font-family: var(--font-heading);
    font-size: 1rem;
    font-weight: 600;
    color: var(--color-accent);
    margin-bottom: 0.5rem;
}

.focus-item p {
    font-size: 0.95rem;
    margin-bottom: 0;
}

.email {
    font-family: var(--font-heading);
    font-size: 1.1rem;
    color: var(--color-accent);
    background: var(--color-accent-light);
    display: inline-block;
    padding: 0.5rem 1rem;
    border-radius: 4px;
}

footer {
    max-width: var(--max-width);
    margin: 4rem auto 0 auto;
    padding-top: 2rem;
    border-top: 1px solid var(--color-border);
    font-size: 0.9rem;
    color: #888;
    text-align: center;
}

